lines = ["package com.example.plantdetector.utils", "", "object Constants {",
         "    const val INPUT_SIZE = 256", "    const val CONFIDENCE_THRESHOLD = 0.25f", "",
         "    // ترتیب دقیقاً مطابق خروجی مدل TFLite (تأییدشده با کالیبراسیون)",
         "    val CLASS_NAMES = listOf("]
for i, n in enumerate(ORDER):
    comma = "," if i < len(ORDER) - 1 else ""
    lines.append(f'        "{n}"{comma}  // {i}')
lines.append("    )")
lines.append("}")

path = "app/src/main/java/com/example/plantdetector/utils/Constants.kt"
open(path, "w", encoding="utf-8").write("\n".join(lines) + "\n")
